using for..else to cluster dupes into cohorts
matches = (sims.tril(-1)&gt;.995).nonzero().cpu().tolist()
for id, other_id in matches:
for c in cohorts:
if id in c or other_id in c:
c.update((id, other_id))
break
else:
cohorts.append(set((id, other_id)))
